head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnID]<br/>Body Column 의 인덱스값을 사용하여 특정 Body Column 의 ID 를 반환합니다.",
    "validation" : [
        "columnIndex(필수) 파라미터로 ID 를 조회하려는 Body Column 의 인덱스값을 설정해야 합니다. (Body Column 의 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다)",
        "Body Column 의 인덱스값을 사용하여 특정 Body Column 의 ID 를 반환해야 합니다.",
        "사용자에 의해 Column 의 순서가 변경되어도 Body Column 의 인덱스값은 변경되지 않습니다.",
        "파라미터에 해당하는 Body Column 이 없는 경우 null 을 반환해야 합니다.",
        "RowNum, RowStatus Column 은 인덱스에 포함되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - rowNumVisible / rowStatusVisible 로 RowNum·RowStatus Column 표시 → 이들은 getColumnID 인덱스에서 제외
    //  - Body Column 인덱스 : 0:name / 1:birth / 2:dept(숨김) / 3:amount  (숨겨진 dept 도 인덱스에 포함)
    $c.gcm.createLabel('label="RowNum·RowStatus Column 표시(인덱스 제외) / Body Column → 0:name, 1:birth, 2:dept(숨김), 3:amount (숨김 컬럼도 인덱스 포함). columnMove=true 로 헤더 드래그 순서변경 가능."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="birth" name="birth" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "HONG", "birth": "19850315", "dept": "영업", "amount": 1000 },
        { "name": "KIM",  "birth": "19900720", "dept": "개발", "amount": 2000 },
        { "name": "LEE",  "birth": "19880103", "dept": "기획", "amount": 3000 },
        { "name": "PARK", "birth": "19920512", "dept": "총무", "amount": 4000 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (createCList 공통 함수)
    //  - rowNumVisible="true"    : RowNum Column 표시 (getColumnID 인덱스 제외 @spec1)
    //  - rowStatusVisible="true" : RowStatus Column 표시 (getColumnID 인덱스 제외 @spec1)
    //  - columnMove="true"       : 헤더 드래그로 사용자 Column 순서변경 허용 (#3)
    let properties = {
        dataList: "data:dlt_bind",
        rowNumVisible: "true",
        rowStatusVisible: "true",
        columnMove: "true",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Body 4컬럼)
    // 마지막 amount 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:720px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnID 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="생년월일"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="부서(숨김)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text)
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : birth (text)
    strTarget += '<w2:column width="120" style="" inputType="text" id="birth" dataList="birth"></w2:column>';
    // index 2 : dept (text) - 숨김 처리 대상 (숨겨도 인덱스에는 포함됨)
    strTarget += '<w2:column width="120" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    // index 3 : amount (number + displayFormat), width="*"
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // dept(인덱스 2) Column 숨김 처리 → 숨겨진 Column 도 getColumnID 인덱스에 포함됨을 검증
    target1.setColumnVisible(2, false);
}



// getColumnID 확인 : par_columnIndex(Body Column 인덱스) 로 호출 → 해당 Body Column 의 ID 반환
//  - 0 → name / 1 → birth / 2 → dept(숨김, 인덱스 포함) / 3 → amount
//  - 99 (범위 밖) → null
//  - RowNum/RowStatus Column 은 인덱스 제외 → 인덱스 0 은 첫 Body 데이터 컬럼(name)
scwin.btn_getColumnID_onclick = function () {
    let colIndex = Number(par_columnIndex.getValue());
    let rtn = target1.getColumnID(colIndex);

    // 반환값이 null 인 경우와 ID 인 경우를 구분하여 출력
    let out = "getColumnID(" + colIndex + ") → " + (rtn === null ? "null" : rtn);
    wf_body_bottom.getObj("scwin").setReturnValue(out);
}
